var assert = require('assert');
var ms = require('./');


describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that non-string values with length property (like arrays) are not parsed
    // The original code correctly rejects non-strings, but the patch allows any value with length > 0
    assert.throws(() => ms([1, 2, 3]), /val is not a non-empty string or a valid number/);

    // Also test that strings are still handled correctly
    assert.strictEqual(ms('1s'), 1000);
    assert.strictEqual(ms('1m'), 60000);

    // The patch should break behavior for non-strings with length property
    // For example, an array with length > 0 should not be parsed
    assert.throws(() => ms([1, 2, 3]), /val is not a non-empty string or a valid number/);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The change modifies the threshold for pluralization from >= 1.5 to > 1.5
    // This affects cases where msAbs == n * 1.5
    // For example, 90000 ms is exactly 1.5 minutes (90000 = 60000 * 1.5)
    // Under the original code, this would be plural: "1.5 minutes" → "2 minutes"
    // But under the new code, since 90000 > 60000 * 1.5 is false (it's equal),
    // it would be singular: "2 minute"
    // The original behavior was to use plural when >= 1.5, so 90000 ms should be "2 minutes"
    // The new behavior produces "2 minute", which is incorrect
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original behavior: 1 year = 365.25 days → correct
    // The patched behavior: 1 year = 1/365.25 days → wrong
    // So the original should parse '1y' to ~31.5576e9 ms
    // The patched version will parse it to ~1.997e6 ms (about 24 minutes)

    const expected = 365.25 * 24 * 60 * 60 * 1000; // ~31.5576e9 ms
    const result = ms('1y');

    // The original version should give the correct year value
    // The patched version should NOT
    // So we check: original passes, patched fails
    assert.strictEqual(typeof result, 'number', 'result should be a number');
    assert.strictEqual(result, expected, 'original should parse 1y correctly');
  });
});

